INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Q0Q6E', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'If \\( 5x + 4y = 38 \\) and \\( 2x - 4y = 4 \\), what is the value of \\( 3x - 2y + 7 \\)?', NULL, $lyceon_json$[{"key":"A","text":"\\( 14 \\)"},{"key":"B","text":"\\( 21 \\)"},{"key":"C","text":"\\( 25 \\)"},{"key":"D","text":"\\( 29 \\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates \\( y \\): \\( (5x + 4y) + (2x - 4y) = 38 + 4 \\), giving \\( 7x = 42 \\), so \\( x = 6 \\). Substituting into the second equation: \\( 2(6) - 4y = 4 \\), so \\( 12 - 4y = 4 \\), giving \\( y = 2 \\). Therefore \\( 3x - 2y + 7 = 3(6) - 2(2) + 7 = 18 - 4 + 7 = 21 \\). The value 14 results from computing \\( 3(6) - 2(2) = 14 \\) but forgetting to add the constant 7, stopping one step short. The value 25 results from omitting the \\( -2y \\) term entirely and computing \\( 3(6) + 7 = 25 \\). The value 29 results from a sign error, treating \\( -2y \\) as \\( +2y \\) and computing \\( 3(6) + 2(2) + 7 = 18 + 4 + 7 = 29 \\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20Y0UD2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A survey of $400$ pet owners found that $148$ own at least one cat. What percentage of the surveyed pet owners own at least one cat?', NULL, $lyceon_json$[{"key":"A","text":"$27\\%$"},{"key":"B","text":"$37\\%$"},{"key":"C","text":"$40\\%$"},{"key":"D","text":"$63\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The percentage is $\\frac{148}{400} \\times 100 = 37\\%$. The value $27\\%$ results from a computational error such as misreading $148$ as $108$. The value $40\\%$ comes from rounding $148$ up to $160$ or estimating imprecisely. The value $63\\%$ is the complement ($100\\% - 37\\%$), which gives the percentage who do not own a cat rather than those who do.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22IM1CF', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'Solution X contains acid and water in a ratio of $2:9$ by volume. Solution Y contains acid and water in a ratio of $5:11$ by volume. A chemist combines $44$ milliliters of Solution X with $48$ milliliters of Solution Y. What fraction of the resulting mixture is acid?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{20}$"},{"key":"B","text":"$\\frac{1}{4}$"},{"key":"C","text":"$\\frac{1}{3}$"},{"key":"D","text":"$\\frac{23}{48}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Solution X has $2 + 9 = 11$ parts total, so $44$ mL of X contains $\\frac{2}{11} \\times 44 = 8$ mL of acid. Solution Y has $5 + 11 = 16$ parts total, so $48$ mL of Y contains $\\frac{5}{16} \\times 48 = 15$ mL of acid. Total acid is $8 + 15 = 23$ mL out of $44 + 48 = 92$ mL total, giving $\\frac{23}{92} = \\frac{1}{4}$. The value $\\frac{7}{20}$ results from naively adding the ratio numerators and denominators ($\\frac{2+5}{9+11}$). The value $\\frac{1}{3}$ results from dividing total acid by total water ($\\frac{23}{69}$) instead of by total volume. The value $\\frac{23}{48}$ results from dividing total acid by only the volume of Solution Y.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22QYTCL', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A fruit vendor sold a total of 53 mangoes and papayas on Saturday. Each mango was sold for \\$3 and each papaya for \\$7. If the total revenue was \\$247, how many papayas were sold?', NULL, $lyceon_json$[{"key":"A","text":"\\( 17 \\)"},{"key":"B","text":"\\( 22 \\)"},{"key":"C","text":"\\( 31 \\)"},{"key":"D","text":"\\( 36 \\)"}]$lyceon_json$::jsonb, 'B', NULL, E'Let \\( m \\) be the number of mangoes and \\( p \\) be the number of papayas. The system is \\( m + p = 53 \\) and \\( 3m + 7p = 247 \\). From the first equation, \\( m = 53 - p \\). Substituting: \\( 3(53 - p) + 7p = 247 \\), so \\( 159 - 3p + 7p = 247 \\), giving \\( 4p = 88 \\) and \\( p = 22 \\). Thus 22 papayas were sold. Choosing 31 results from solving correctly but reporting the number of mangoes (\\( m = 53 - 22 = 31 \\)) instead of papayas. Choosing 17 comes from an arithmetic slip such as computing \\( 4p = 68 \\) by subtracting incorrectly. Choosing 36 arises from reversing the prices in the revenue equation, setting up \\( 7m + 3p = 247 \\).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM235NVVL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone has a height of $20$ and a base radius of $15$. A plane parallel to the base cuts the cone at a height of $12$ from the base, creating a frustum (the portion between the base and the cut). What is the volume of the frustum?', NULL, $lyceon_json$[{"key":"A","text":"$96\\pi$"},{"key":"B","text":"$1404\\pi$"},{"key":"C","text":"$1500\\pi$"},{"key":"D","text":"$4212\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $1404\\pi$. The frustum''s volume is the volume of the original cone minus the volume of the small cone removed from the top. The original cone has volume $\\frac{1}{3}\\pi(15^2)(20) = 1500\\pi$. The cut is at height $12$ from the base, so the small cone above the cut has height $20 - 12 = 8$. By similar triangles, the small cone''s radius is $15 \\times \\frac{8}{20} = 6$, and its volume is $\\frac{1}{3}\\pi(6^2)(8) = 96\\pi$. Therefore the frustum volume is $1500\\pi - 96\\pi = 1404\\pi$. The value $96\\pi$ is the volume of the removed small cone only. The value $1500\\pi$ is the volume of the full cone without subtracting the removed portion. The value $4212\\pi$ results from using $\\pi r^2 h$ for each cone instead of $\\frac{1}{3}\\pi r^2 h$, omitting the $\\frac{1}{3}$ factor.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM246UDUX', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A small electronics workshop produces circuit boards and sensor modules. Each circuit board requires 3 hours of labor and each sensor module requires 5 hours. The workshop has at most 97 labor hours available per week. If the workshop must produce at least 7 sensor modules per week to fulfill standing orders, what is the maximum number of circuit boards it can produce per week?', NULL, $lyceon_json$[{"key":"A","text":"\\( 20 \\)"},{"key":"B","text":"\\( 21 \\)"},{"key":"C","text":"\\( 24 \\)"},{"key":"D","text":"\\( 32 \\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Let \\( c \\) be the number of circuit boards and \\( s \\) be the number of sensor modules. The constraints are \\( 3c + 5s \\leq 97 \\) and \\( s \\geq 7 \\). To maximize \\( c \\), use the minimum value \\( s = 7 \\): substituting gives \\( 3c + 35 \\leq 97 \\), so \\( 3c \\leq 62 \\) and \\( c \\leq 20.\\overline{6} \\). Since \\( c \\) must be a whole number, the maximum is 20. Choosing 21 comes from rounding 20.67 up instead of down, ignoring that 21 circuit boards would require \\( 63 + 35 = 98 \\) hours, which exceeds the limit. Choosing 24 results from using \\( s = 5 \\) instead of the required minimum of 7, giving \\( 3c + 25 \\leq 97 \\) and \\( c \\leq 24 \\). Choosing 32 results from ignoring the sensor module constraint entirely and computing \\( 97 \\div 3 \\approx 32.3 \\), rounding down to 32.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM24915IC', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $5$ members of a town council are $31$, $37$, $43$, $47$, and $52$. What is the median age of these council members?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$40$"},{"key":"C","text":"$42$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'D', NULL, E'With $5$ values listed in order, the median is the $3$rd value: $43$. The value $37$ is the $2$nd value, not the middle one. The value $40$ results from averaging the $2$nd and $3$rd values ($\\frac{37+43}{2}$), a method appropriate for an even number of data points but not for an odd number. The value $42$ is the mean ($\\frac{31+37+43+47+52}{5} = \\frac{210}{5} = 42$), which is a different measure of center than the median.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM254AOLM', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $\\frac{3(2x + 7)}{4} - 5 = x + 2$, what is the value of $6x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"$-20$"},{"key":"B","text":"$20$"},{"key":"C","text":"$22$"},{"key":"D","text":"$\\frac{7}{2}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Add $5$ to both sides to get $\\frac{3(2x + 7)}{4} = x + 7$. Multiply both sides by $4$: $3(2x + 7) = 4(x + 7)$. Expand: $6x + 21 = 4x + 28$. Subtract $4x$ from both sides: $2x + 21 = 28$. Subtract $21$: $2x = 7$, so $x = \\frac{7}{2}$. The question asks for $6x - 1$, not $x$: $6 \\cdot \\frac{7}{2} - 1 = 21 - 1 = 20$. The value $\\frac{7}{2}$ is the result of solving for $x$ but not evaluating the requested expression. The value $22$ comes from computing $21 + 1$ instead of $21 - 1$. The value $-20$ results from a sign error in the final computation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25K2E4G', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows the relationship between hours of sunlight per day ($x$) and the height of a plant in centimeters ($y$). The line of best fit is $y = 2.3x + 4.1$. According to this model, what is the predicted height, in centimeters, of a plant that receives $9$ hours of sunlight per day?', NULL, $lyceon_json$[{"key":"A","text":"$6.4$"},{"key":"B","text":"$20.7$"},{"key":"C","text":"$24.8$"},{"key":"D","text":"$57.6$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 9$: $y = 2.3(9) + 4.1 = 20.7 + 4.1 = 24.8$. The value $6.4$ results from adding the slope and intercept without substituting ($2.3 + 4.1$). The value $20.7$ results from computing only $2.3 \\times 9$ and omitting the $y$-intercept. The value $57.6$ results from multiplying both the slope and intercept by $9$: $(2.3 + 4.1) \\times 9 = 57.6$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25YL6U8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle in the $xy$-plane has equation $(x + 5)^2 + (y - 3)^2 = 121$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{11}$"},{"key":"B","text":"$11$"},{"key":"C","text":"$22$"},{"key":"D","text":"$121$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $11$. The standard form of a circle is $(x - h)^2 + (y - k)^2 = r^2$, where $r$ is the radius. Here $r^2 = 121$, so $r = \\sqrt{121} = 11$. The value $\\sqrt{11}$ comes from taking the square root of $11$ rather than $121$, confusing the radius with the square root of the radius. The value $22$ results from computing the diameter instead of the radius. The value $121$ comes from reporting $r^2$ instead of $r$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27NVCZ4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set consists of $8$ values: $12$, $15$, $18$, $22$, $22$, $27$, $31$, $33$. If the value $33$ is replaced by $61$, which of the following measures of the data set will change?', NULL, $lyceon_json$[{"key":"A","text":"Mean only"},{"key":"B","text":"Median only"},{"key":"C","text":"Mean and range only"},{"key":"D","text":"Mean, median, and range"}]$lyceon_json$::jsonb, 'C', NULL, E'Original mean: $\\frac{12+15+18+22+22+27+31+33}{8} = \\frac{180}{8} = 22.5$. New mean: $\\frac{180-33+61}{8} = \\frac{208}{8} = 26$. The mean changes. Original range: $33-12=21$. New range: $61-12=49$. The range changes. The median is the average of the $4$th and $5$th values. Both before and after the change, these are $22$ and $22$, so the median remains $22$. Therefore, the mean and range change but the median does not. Selecting mean only overlooks the change in range. Selecting median only is incorrect because the two middle values are unchanged. Including median with the other two is incorrect for the same reason.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM287MWOT', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The functions $f$ and $g$ are defined by $f(x) = x^2 - 2x$ and $g(x) = 3x + 4$. If $f(g(a)) = 0$ and $a \\neq -\\frac{4}{3}$, what is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{2}{3}$"},{"key":"B","text":"$-\\frac{4}{3}$"},{"key":"C","text":"$\\frac{2}{3}$"},{"key":"D","text":"$-2$"}]$lyceon_json$::jsonb, 'A', NULL, E'First, note that $f(x) = x^2 - 2x = x(x - 2)$, so $f(x) = 0$ when $x = 0$ or $x = 2$. Setting $g(a) = 0$: $3a + 4 = 0$, giving $a = -\\frac{4}{3}$. Setting $g(a) = 2$: $3a + 4 = 2$, giving $a = -\\frac{2}{3}$. Since the problem excludes $a = -\\frac{4}{3}$, the answer is $a = -\\frac{2}{3}$. The distractor $-\\frac{4}{3}$ is the excluded solution from $g(a) = 0$. The distractor $\\frac{2}{3}$ results from a sign error when solving $3a + 4 = 2$, incorrectly obtaining $3a = 2 - 4 = -2$ but dropping the negative. The distractor $-2$ comes from incorrectly setting $g(a) = -2$ instead of $g(a) = 2$, solving $3a + 4 = -2$ to get $a = -2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28E282I', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'The graphs of $y = 2x + 1$ and $y = x^2 + x - 5$ intersect at two points. What is the sum of the $y$-coordinates of these two intersection points?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Setting the equations equal: $2x + 1 = x^2 + x - 5$. Rearranging: $0 = x^2 - x - 6$, which factors as $(x - 3)(x + 2) = 0$. The solutions are $x = 3$ and $x = -2$. Substituting into $y = 2x + 1$: when $x = 3$, $y = 7$; when $x = -2$, $y = -3$. The sum of the $y$-coordinates is $7 + (-3) = 4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29WU8FC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $p$ satisfies $p(2) = 19$ and $p(8) = -5$. What is $p(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$27$"},{"key":"D","text":"$7$"}]$lyceon_json$::jsonb, 'D', NULL, E'The rate of change is $\\frac{-5 - 19}{8 - 2} = \\frac{-24}{6} = -4$. Using point-slope form with the point $(2, 19)$: $p(x) = -4(x - 2) + 19 = -4x + 8 + 19 = -4x + 27$. Therefore $p(5) = -4(5) + 27 = -20 + 27 = 7$. The value $-7$ arises from a sign error, such as computing $-27 + 20$. The value $-1$ comes from incorrectly treating $19$ as the $y$-intercept and computing $-4(5) + 19 = -1$. The value $27$ is the $y$-intercept of the function, not its value at $x = 5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A217I5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $7$ red chips, $4$ blue chips, and $3$ green chips. If one chip is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{7}$"},{"key":"B","text":"$\\frac{2}{7}$"},{"key":"C","text":"$\\frac{3}{14}$"},{"key":"D","text":"$\\frac{4}{7}$"}]$lyceon_json$::jsonb, 'B', NULL, E'There are $7 + 4 + 3 = 14$ chips total. The probability of selecting a blue chip is $\\frac{4}{14} = \\frac{2}{7}$. The value $\\frac{1}{7}$ results from dividing by an incorrect total or miscounting blue chips as $2$ instead of $4$. The value $\\frac{3}{14}$ uses the count of green chips ($3$) instead of blue chips ($4$). The value $\\frac{4}{7}$ results from dividing the number of blue chips by the number of red chips only, rather than by the total number of all chips.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ANWI1U', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'If $f(x) = -3x + 22$, what is $f(7)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1', ARRAY['1'], E'Substitute $x = 7$ into the function: $f(7) = -3(7) + 22 = -21 + 22 = 1$. A common error is computing $-3(7)$ as $21$ instead of $-21$, which would give $21 + 22 = 43$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AV2VWH', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A school''s enrollment increased from $1{,}150$ students to $1{,}311$ students. What is the percent increase in enrollment?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The increase is $1{,}311 - 1{,}150 = 161$ students. The percent increase is $\\frac{161}{1{,}150} \\times 100 = 14\\%$. A common error is dividing the increase by the new enrollment ($\\frac{161}{1{,}311} \\approx 12.3\\%$), which gives the wrong base. Another error is computing $\\frac{1{,}311}{1{,}150} = 1.14$ and reporting $1.14$ or $114$ instead of recognizing that the increase is $14\\%$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C6U22E', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $MNP$ with the right angle at $N$, $\\cos(M) = \\frac{3}{7}$. If $MN = 21$, what is the length of the hypotenuse $MP$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$49$"},{"key":"C","text":"$63$"},{"key":"D","text":"$147$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $49$. Since $\\cos(M) = \\frac{\\text{adjacent}}{\\text{hypotenuse}} = \\frac{MN}{MP}$, we have $\\frac{3}{7} = \\frac{21}{MP}$. Cross-multiplying gives $3 \\cdot MP = 147$, so $MP = 49$. The value $9$ results from incorrectly computing $MP = MN \\times \\cos(M) = 21 \\times \\frac{3}{7}$, which inverts the relationship between adjacent side and hypotenuse. The value $63$ comes from multiplying $21 \\times 3$ without properly using the ratio. The value $147$ results from multiplying $21 \\times 7$ without dividing by $3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DA0PV1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A parallelogram has a base of $17$ cm and a height of $9$ cm. What is the area, in square centimeters, of the parallelogram?', NULL, $lyceon_json$[{"key":"A","text":"$153$"},{"key":"B","text":"$52$"},{"key":"C","text":"$76.5$"},{"key":"D","text":"$306$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $153$ square centimeters. The area of a parallelogram is base times height: $17 \\times 9 = 153$. The value $52$ is the perimeter $2(17 + 9)$, not the area — this error reflects confusing area with perimeter. The value $76.5$ results from dividing the product by $2$ as though the shape were a triangle. The value $306$ comes from doubling the correct area, perhaps by incorrectly accounting for both pairs of parallel sides.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAOR5V', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'What is the value of \\( x \\) in the solution to the system of equations below?\\n\\n\\( 3x + y = 23 \\)\\n\\( x - y = 9 \\)', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '8', ARRAY['8'], E'Adding the two equations eliminates \\( y \\): \\( (3x + y) + (x - y) = 23 + 9 \\), which gives \\( 4x = 32 \\), so \\( x = 8 \\). To verify, substituting back gives \\( y = 8 - 9 = -1 \\), and checking the first equation: \\( 3(8) + (-1) = 24 - 1 = 23 \\). A common error is subtracting the equations instead of adding, which does not directly isolate \\( x \\). Another error is dividing 32 by 3 instead of 4, confusing the coefficient count.', NULL, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DFQ1SE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A school district conducted a study to evaluate a new after-school tutoring program. Students at $5$ schools were offered voluntary enrollment; $180$ students enrolled and $220$ comparable students did not. At the end of the semester, the enrolled students scored an average of $11$ points higher on a standardized math assessment. A district administrator claims the tutoring program caused the improvement. Which of the following is the most significant threat to the validity of this causal claim?', NULL, $lyceon_json$[{"key":"A","text":"The sample included only $5$ schools, which may not represent all schools in the district."},{"key":"B","text":"Students who chose to enroll may have been more motivated academically than those who did not, creating a self-selection bias."},{"key":"C","text":"The standardized math assessment may not align perfectly with the tutoring curriculum."},{"key":"D","text":"The $11$-point difference might not be statistically significant given the sample sizes."}]$lyceon_json$::jsonb, 'B', NULL, E'Because enrollment was voluntary rather than randomly assigned, students who chose to participate may differ systematically from those who did not. Students who voluntarily enrolled may have been more motivated, had more parental support, or had stronger academic foundations — all confounding variables that could explain the higher scores independently of the tutoring itself. This self-selection bias is the most significant threat to the causal claim. Limited school representation affects generalizability but does not directly undermine the causal inference within the studied population. Alignment between the assessment and curriculum is a measurement concern, not a threat to causation. While statistical significance matters, the question is about the study design flaw that undermines the causal claim, and self-selection is the primary structural weakness.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DPR3FT', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Researchers survey two independent random samples of adults in different counties. In County $A$ ($n = 350$), $39\\%$ reported regular exercise, with a $95\\%$ confidence interval of $33.9\\%$ to $44.1\\%$. In County $B$ ($n = 420$), $51\\%$ reported regular exercise, with a $95\\%$ confidence interval of $46.2\\%$ to $55.8\\%$. Based on these confidence intervals, which of the following conclusions is best supported?', NULL, $lyceon_json$[{"key":"A","text":"The difference between the two counties is not statistically significant because neither interval contains $50\\%$."},{"key":"B","text":"County $B$ has a higher exercise rate because its sample percentage is larger."},{"key":"C","text":"There is convincing evidence that the proportion of adults who exercise regularly is higher in County $B$ than in County $A$ because the confidence intervals do not overlap."},{"key":"D","text":"No valid comparison can be made because the sample sizes are different."}]$lyceon_json$::jsonb, 'C', NULL, E'County $A$''s confidence interval is $33.9\\%$ to $44.1\\%$, and County $B$''s is $46.2\\%$ to $55.8\\%$. Because these intervals do not overlap, there is convincing evidence that the population proportions differ, with County $B$ having the higher rate. Whether either interval contains $50\\%$ is irrelevant to comparing the two counties to each other. Citing only the sample percentages without considering the confidence intervals ignores sampling variability. Different sample sizes do not prevent valid comparisons; both samples were random and each produced a valid confidence interval.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DUAEFV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'grid_in', E'If $\\sin(x°) = \\cos(3x° - 10°)$ where $0 < x < 90$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'Since $\\sin(\\theta) = \\cos(90° - \\theta)$ for all angles, the equation $\\sin(x°) = \\cos(3x° - 10°)$ implies $90° - x° = 3x° - 10°$. Adding $x°$ to both sides gives $90° = 4x° - 10°$, and adding $10°$ yields $100° = 4x°$, so $x = 25$. A common error is using the identity $\\sin(\\theta) = \\cos(\\theta)$, which holds only when $\\theta = 45°$, leading to $x = 45$ and $3(45) - 10 = 125°$, which does not satisfy the original equation. Another error is setting $x = 3x - 10$ directly (without the complementary relationship), which gives $x = 5$, but $\\sin(5°) \\neq \\cos(5°)$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E58XYZ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of $200$ customers at a café found that $82$ ordered coffee, $53$ ordered tea, and $19$ ordered both coffee and tea. If a customer is selected at random from those who ordered coffee, what is the probability that this customer also ordered tea?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{19}{200}$"},{"key":"B","text":"$\\frac{19}{82}$"},{"key":"C","text":"$\\frac{19}{53}$"},{"key":"D","text":"$\\frac{82}{200}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The question asks for a conditional probability: given that the customer ordered coffee, what is the probability they also ordered tea? The denominator is the number who ordered coffee ($82$), and the numerator is the number who ordered both ($19$), giving $\\frac{19}{82}$. Using $200$ as the denominator gives the probability of both events out of all customers, not the conditional probability. Using $53$ as the denominator reverses the condition, finding the probability of coffee given tea. The value $\\frac{82}{200}$ is the probability of ordering coffee regardless of tea.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G6Y5R0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a volume of $675\\pi$ cubic centimeters and a height of $27$ centimeters. What is the radius, in centimeters, of the cylinder?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5', ARRAY['5'], E'The volume of a cylinder is $V = \\pi r^2 h$. Setting $675\\pi = \\pi r^2 (27)$ and dividing both sides by $27\\pi$ gives $r^2 = \\frac{675}{27} = 25$. Taking the positive square root, $r = 5$ cm. A common error is forgetting to take the square root and reporting $r^2 = 25$ as the answer. Another error is dividing $675$ by $27$ incorrectly, leading to a wrong value under the square root.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GEXM2T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on hours of practice ($x$) and performance scores ($y$) for $30$ athletes. The line of best fit is $y = 5.3x + 41.7$. Athlete Z practiced for $7$ hours and earned a performance score of $81$. What is the residual for Athlete Z?', NULL, $lyceon_json$[{"key":"A","text":"$-2.2$"},{"key":"B","text":"$2.2$"},{"key":"C","text":"$39.3$"},{"key":"D","text":"$78.8$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted score is $y = 5.3(7) + 41.7 = 37.1 + 41.7 = 78.8$. The residual is actual minus predicted: $81 - 78.8 = 2.2$. The value $-2.2$ results from reversing the subtraction (predicted minus actual). The value $39.3$ results from subtracting only the intercept from the actual score ($81 - 41.7$), ignoring the slope term. The value $78.8$ is the predicted value itself, given when the student confuses the predicted value with the residual.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GO3FYX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'After two consecutive annual decreases, the population of a town is $63\\%$ of what it was two years ago. If the population decreased by $16\\%$ in the first year, by what percentage did it decrease in the second year?', NULL, $lyceon_json$[{"key":"A","text":"$16\\%$"},{"key":"B","text":"$21\\%$"},{"key":"C","text":"$25\\%$"},{"key":"D","text":"$37\\%$"}]$lyceon_json$::jsonb, 'C', NULL, E'After the first year, the population is $84\\%$ of the original (a $16\\%$ decrease). Let $r$ be the second-year decrease rate. Then $0.84(1 - r) = 0.63$, so $1 - r = \\frac{0.63}{0.84} = 0.75$, giving $r = 0.25 = 25\\%$. The value $16\\%$ incorrectly assumes both years have the same decrease rate, but $0.84 \\times 0.84 = 0.7056 \\neq 0.63$. The value $21\\%$ comes from subtracting the percentages directly ($84\\% - 63\\% = 21$ percentage points), confusing a percentage-point difference with a percent decrease. The value $37\\%$ comes from computing $100\\% - 63\\% = 37\\%$, treating the total two-year change as the second-year decrease alone.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GQ1W85', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A polling organization surveys a random sample of voters and estimates that $44\\%$ favor Candidate $X$, with a margin of error of $\\pm 3.1\\%$. A second independent random sample, twice as large, estimates that $47\\%$ favor Candidate $X$. If the margin of error is inversely proportional to the square root of the sample size, which of the following is closest to the margin of error for the second sample?', NULL, $lyceon_json$[{"key":"A","text":"$1.55\\%$"},{"key":"B","text":"$2.19\\%$"},{"key":"C","text":"$3.1\\%$"},{"key":"D","text":"$4.38\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since the margin of error is inversely proportional to $\\sqrt{n}$, doubling the sample size divides the margin of error by $\\sqrt{2} \\approx 1.414$. So the new margin of error is $\\frac{3.1}{1.414} \\approx 2.19\\%$. Dividing by $2$ instead of $\\sqrt{2}$ gives $1.55\\%$, which incorrectly assumes the margin of error halves when the sample doubles. Keeping $3.1\\%$ ignores that a larger sample reduces the margin. Multiplying by $\\sqrt{2}$ gives $4.38\\%$, which reverses the relationship between sample size and margin of error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H8I4N2', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'As $x$ approaches positive infinity, which of the following best describes the end behavior of $f(x) = -3x^4 + 7x^3 - x + 11$?', NULL, $lyceon_json$[{"key":"A","text":"$f(x)$ approaches positive infinity"},{"key":"B","text":"$f(x)$ approaches negative infinity"},{"key":"C","text":"$f(x)$ approaches $0$"},{"key":"D","text":"$f(x)$ approaches $11$"}]$lyceon_json$::jsonb, 'B', NULL, E'The end behavior of a polynomial is determined by its leading term. Here the leading term is $-3x^4$. Since the degree is even and the leading coefficient is negative, as $x$ approaches positive infinity, $-3x^4$ approaches negative infinity, so $f(x)$ approaches negative infinity. The distractor stating $f(x)$ approaches positive infinity ignores the negative leading coefficient and considers only the even degree. The distractor stating $f(x)$ approaches $0$ confuses polynomial end behavior with that of rational functions where the denominator dominates. The distractor stating $f(x)$ approaches $11$ incorrectly assumes the constant term determines the function''s long-run value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2I6B6SV', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $\\frac{(7x^5)^2}{49x^3}$?', NULL, $lyceon_json$[{"key":"A","text":"$x^7$"},{"key":"B","text":"$7x^7$"},{"key":"C","text":"$x^{10}$"},{"key":"D","text":"$x^{15}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator $(7x^5)^2$ equals $7^2 \\cdot x^{5 \\cdot 2} = 49x^{10}$. Dividing by $49x^3$ gives $\\frac{49x^{10}}{49x^3} = x^{10-3} = x^7$. The distractor $7x^7$ results from failing to recognize that $7^2 = 49$ cancels with the denominator''s $49$, leaving an extra factor of $7$. The distractor $x^{10}$ comes from correctly computing the numerator exponent but neglecting to divide by $x^3$. The distractor $x^{15}$ arises from multiplying the exponents $5 \\times 3 = 15$ instead of subtracting $10 - 3 = 7$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IO3RHT', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'A linear function $g$ is defined such that $g(4) - g(1) = 21$ and $g(9) = 47$. What is the value of $g(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$-9$"},{"key":"C","text":"$-16$"},{"key":"D","text":"$21$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $g$ is linear, its rate of change is constant. The difference $g(4) - g(1)$ spans $4 - 1 = 3$ units of $x$, so the rate of change is $\\frac{21}{3} = 7$. Writing $g(x) = 7x + b$ and using $g(9) = 47$: $7(9) + b = 47$, so $63 + b = 47$, giving $b = -16$. Therefore $g(0) = 7(0) + (-16) = -16$. The value $16$ is a sign error when computing $b = 47 - 63$. The value $-9$ equals $g(1) = 7(1) - 16 = -9$, which is the function evaluated at $1$ rather than at $0$. The value $21$ is the given difference $g(4) - g(1)$, not the value of $g(0)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J26R4B', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'grid_in', E'Two chords $\\overline{AB}$ and $\\overline{CD}$ intersect at point $E$ inside a circle. If $AE = 6$, $EB = 14$, and $CE = 4$, what is the length of $ED$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'By the intersecting chords theorem, when two chords intersect inside a circle, the products of their segments are equal: $AE \\times EB = CE \\times ED$. Substituting the given values, $6 \\times 14 = 4 \\times ED$, so $84 = 4 \\times ED$ and $ED = 21$. A common error is adding the segments instead of multiplying ($6 + 14 = 20$, then setting $4 + ED = 20$ to get $ED = 16$). Another error is setting up the proportion incorrectly as $\\frac{AE}{EB} = \\frac{CE}{ED}$, which gives $\\frac{6}{14} = \\frac{4}{ED}$ and $ED = \\frac{28}{3} \\approx 9.33$.', NULL, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JJK98J', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'In a factory, Machine $P$ produces $60\\%$ of all parts and Machine $Q$ produces the remaining $40\\%$. Of the parts produced by Machine $P$, $3\\%$ are defective. Of the parts produced by Machine $Q$, $7\\%$ are defective. A randomly selected part is found to be defective. What is the probability that it was produced by Machine $Q$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{25}$"},{"key":"B","text":"$\\frac{14}{23}$"},{"key":"C","text":"$\\frac{9}{23}$"},{"key":"D","text":"$\\frac{7}{46}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Using Bayes\\u2019 theorem, the probability that a defective part came from Machine $Q$ is $\\frac{P(\\text{defective}|Q) \\cdot P(Q)}{P(\\text{defective})}$. The total defect rate is $0.60 \\times 0.03 + 0.40 \\times 0.07 = 0.018 + 0.028 = 0.046$. The probability from Machine $Q$ given defective is $\\frac{0.028}{0.046} = \\frac{14}{23}$. The value $\\frac{7}{25}$ comes from using only Machine $Q$''s defect rate ($7\\%$) divided by the sum of both defect rates ($3\\% + 7\\% = 10\\%$), ignoring the production proportions. The value $\\frac{9}{23}$ results from swapping the machines in the numerator, computing $\\frac{0.018}{0.046} = \\frac{9}{23}$, which gives the probability the defective part came from Machine $P$ rather than Machine $Q$. The value $\\frac{7}{46}$ results from using $0.07$ alone in the numerator instead of $0.40 \\times 0.07 = 0.028$, forgetting to weight the defect rate by Machine $Q$''s production share.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JXVT7M', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $4x + 19 = 71$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Subtract $19$ from both sides to get $4x = 52$, then divide both sides by $4$ to get $x = 13$. A common error is forgetting to divide by $4$ and reporting $52$, which is only the value of $4x$, not $x$ itself.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KL1FO8', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a $45°$-$45°$-$90°$ triangle, each leg has length $9\\sqrt{2}$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$18$"},{"key":"C","text":"$18\\sqrt{2}$"},{"key":"D","text":"$9\\sqrt{3}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $18$. In a $45°$-$45°$-$90°$ triangle, the hypotenuse equals the leg times $\\sqrt{2}$. So the hypotenuse is $9\\sqrt{2} \\times \\sqrt{2} = 9 \\times 2 = 18$. The value $9$ comes from dividing the leg by $\\sqrt{2}$ instead of multiplying, reflecting a reversal of the relationship. The value $18\\sqrt{2}$ results from multiplying by $\\sqrt{2}$ twice (applying the rule to the already-computed hypotenuse). The value $9\\sqrt{3}$ arises from confusing the $45°$-$45°$-$90°$ ratio with the $30°$-$60°$-$90°$ ratio.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LC2V6U', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $(x + 7)^2 - (x - 7)^2$?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$14x$"},{"key":"C","text":"$28x$"},{"key":"D","text":"$2x^2 + 98$"}]$lyceon_json$::jsonb, 'C', NULL, E'Expanding: $(x+7)^2 = x^2 + 14x + 49$ and $(x-7)^2 = x^2 - 14x + 49$. Subtracting gives $(x^2 + 14x + 49) - (x^2 - 14x + 49) = 28x$. Alternatively, using the difference of squares identity $a^2 - b^2 = (a+b)(a-b)$ with $a = x+7$ and $b = x-7$: $(2x)(14) = 28x$. The distractor $0$ results from incorrectly assuming $(x+7)^2$ and $(x-7)^2$ are equal. The distractor $14x$ comes from only accounting for one of the two cross-term contributions of $14x$. The distractor $2x^2 + 98$ results from adding the two squared expressions instead of subtracting them.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LISNFO', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = 2x^2 - 11x + 5$. What is the value of $f(-4)$?', NULL, $lyceon_json$[{"key":"A","text":"$81$"},{"key":"B","text":"$-7$"},{"key":"C","text":"$41$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = -4$: $f(-4) = 2(-4)^2 - 11(-4) + 5 = 2(16) + 44 + 5 = 32 + 44 + 5 = 81$. The distractor $-7$ results from treating $-11(-4)$ as $-11(4) = -44$, computing $32 - 44 + 5 = -7$, a sign error on the middle term. The distractor $41$ comes from not squaring the input, computing $2(-4) - 11(-4) + 5 = -8 + 44 + 5 = 41$. The distractor $17$ results from incorrectly evaluating $(-4)^2$ as $-16$, computing $2(-16) - 11(-4) + 5 = -32 + 44 + 5 = 17$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LZ7VM0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A recipe for mortar mix requires $7$ bags of sand for every $2$ bags of cement. If a contractor needs a total of $63$ bags of the mix, how many bags of cement does the contractor need?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '14', ARRAY['14'], E'The ratio of sand to cement is $7:2$, so the total number of parts is $7 + 2 = 9$. Out of every $9$ bags, $2$ are cement. For $63$ total bags: $\\frac{2}{9} \\times 63 = 14$ bags of cement. A common error is dividing $63$ by $2$ to get $31.5$, which ignores the total-parts relationship. Another error is computing $\\frac{7}{9} \\times 63 = 49$, which gives the sand quantity instead.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MRX0B6', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to $(3x + 11)(x - 2) = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -\\frac{11}{3}$ and $x = 2$"},{"key":"B","text":"$x = \\frac{11}{3}$ and $x = 2$"},{"key":"C","text":"$x = -\\frac{11}{3}$ and $x = -2$"},{"key":"D","text":"$x = \\frac{3}{11}$ and $x = 2$"}]$lyceon_json$::jsonb, 'A', NULL, E'By the zero product property, either $3x + 11 = 0$ or $x - 2 = 0$. From $3x + 11 = 0$: $3x = -11$, so $x = -\\frac{11}{3}$. From $x - 2 = 0$: $x = 2$. The distractor $x = \\frac{11}{3}$ and $x = 2$ results from a sign error when solving $3x + 11 = 0$ (dividing $11$ by $3$ without the negative). The distractor $x = -\\frac{11}{3}$ and $x = -2$ applies a sign error to the second factor, solving $x - 2 = 0$ as $x = -2$. The distractor $x = \\frac{3}{11}$ and $x = 2$ results from inverting the fraction when isolating $x$ from $3x + 11 = 0$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O3UN7X', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'The line $5x + 2y = 34$ passes through the point $(a, 7)$. What is the value of $a$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '4', ARRAY['4'], E'Substitute $y = 7$ into the equation: $5a + 2(7) = 34$, which gives $5a + 14 = 34$. Subtract $14$ from both sides to get $5a = 20$, then divide by $5$ to find $a = 4$. A common error is subtracting $2(7)$ incorrectly or forgetting to divide by $5$, which would yield an intermediate value of $20$ rather than the final answer.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O9VHNR', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The mean of a data set containing $9$ values is $47$. When two additional values, $p$ and $q$, are included, the mean of all $11$ values becomes $51$. If $p = 2q$, what is the value of $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '46', ARRAY['46'], E'The sum of the original $9$ values is $9 \\times 47 = 423$. The sum of all $11$ values is $11 \\times 51 = 561$. Therefore $p + q = 561 - 423 = 138$. Substituting $p = 2q$ gives $2q + q = 138$, so $3q = 138$ and $q = 46$. A common error is dividing $138$ by $2$ (getting $69$) by forgetting the relationship $p = 2q$. Another error is computing the new sum as $9 \\times 51 = 459$ instead of $11 \\times 51 = 561$, leading to incorrect values.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QOU8OU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, $\\angle P = 51°$ and $\\angle Q$ is twice $\\angle R$. What is the measure, in degrees, of $\\angle R$?', NULL, $lyceon_json$[{"key":"A","text":"$43°$"},{"key":"B","text":"$51°$"},{"key":"C","text":"$86°$"},{"key":"D","text":"$129°$"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is $43°$. The sum of angles in a triangle is $180°$. Setting $\\angle R = r$, we have $51 + 2r + r = 180$, so $3r = 129$ and $r = 43°$. The value $51°$ comes from misreading the question and reporting $\\angle P$ instead of $\\angle R$. The value $86°$ is $2 \\times 43°$, which is $\\angle Q$, not $\\angle R$, reflecting incomplete reasoning. The value $129°$ results from computing $180° - 51° = 129°$ and stopping without dividing by $3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RZFFJD', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the slope of the line $3x - 7y = 28$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{7}$"},{"key":"B","text":"$-\\frac{3}{7}$"},{"key":"C","text":"$\\frac{7}{3}$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'Rewrite the equation in slope-intercept form by isolating $y$: subtract $3x$ from both sides to get $-7y = -3x + 28$, then divide every term by $-7$ to get $y = \\frac{3}{7}x - 4$. The slope is $\\frac{3}{7}$. The value $-\\frac{3}{7}$ results from neglecting the sign change when dividing $-3x$ by $-7$. The value $\\frac{7}{3}$ comes from inverting the fraction, confusing the roles of the coefficients. The value $3$ results from reading the coefficient of $x$ directly from the original equation without converting to slope-intercept form.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SCS5M0', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which value of \\( x \\) satisfies the inequality \\( 9x + 4 < 67 \\)?', NULL, $lyceon_json$[{"key":"A","text":"\\( 5 \\)"},{"key":"B","text":"\\( 7 \\)"},{"key":"C","text":"\\( 8 \\)"},{"key":"D","text":"\\( 11 \\)"}]$lyceon_json$::jsonb, 'A', NULL, E'Solving \\( 9x + 4 < 67 \\): subtract 4 from both sides to get \\( 9x < 63 \\), then divide by 9 to get \\( x < 7 \\). Among the choices, only 5 is less than 7. The value 7 is wrong because the inequality is strict (less than, not less than or equal to). The value 8 results from an arithmetic slip such as computing \\( 67 - 4 = 72 \\) and finding \\( x < 8 \\). The value 11 ignores the direction of the inequality entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SGRG1P', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A ceramics studio uses $13$ pounds of clay to produce $4$ vases. At this rate, how many pounds of clay are needed to produce $28$ vases?', NULL, $lyceon_json$[{"key":"A","text":"$52$"},{"key":"B","text":"$84$"},{"key":"C","text":"$91$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'C', NULL, E'The rate is $\\frac{13 \\text{ pounds}}{4 \\text{ vases}}$. For $28$ vases: $\\frac{13}{4} \\times 28 = 91$ pounds. The value $52$ results from multiplying $13 \\times 4$ instead of setting up the proportion. The value $84$ comes from an incorrect ratio of $3$ pounds per vase ($3 \\times 28$). The value $112$ comes from multiplying $28 \\times 4$, treating the number of vases per unit of clay as the rate rather than the reverse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2SI0WUM', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A pharmaceutical company tests a new allergy medication by randomly assigning $300$ volunteers to either a treatment group (receiving the medication) or a control group (receiving a placebo). Neither the volunteers nor the doctors administering the treatment know which group each volunteer is in. After $8$ weeks, the treatment group reports significantly fewer allergy symptoms. Which feature of this study design allows the researchers to conclude that the medication likely caused the reduction in symptoms?', NULL, $lyceon_json$[{"key":"A","text":"The large number of volunteers in the study"},{"key":"B","text":"The use of random assignment to treatment and control groups"},{"key":"C","text":"The fact that the study lasted $8$ weeks"},{"key":"D","text":"The double-blind design preventing bias in symptom reporting"}]$lyceon_json$::jsonb, 'B', NULL, E'Random assignment is the feature that allows causal conclusions. By randomly assigning participants to treatment and control groups, the study design ensures that confounding variables are approximately balanced between groups, so any observed difference can be attributed to the treatment. A large sample size increases precision and statistical power but does not by itself establish causation. The duration of the study relates to measuring the outcome adequately, not to establishing a causal link. The double-blind design reduces bias in reporting and assessment, which strengthens the study''s internal validity, but it is random assignment specifically that enables causal inference.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMOP6K', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher records the number of hours $150$ college students spend on social media per day and their grade point averages. The researcher finds that students who spend more time on social media tend to have lower GPAs. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Spending more time on social media causes lower GPAs."},{"key":"B","text":"There is an association between social media usage and GPA among these students."},{"key":"C","text":"Reducing social media usage will improve a student's GPA."},{"key":"D","text":"Students with lower GPAs are forced to spend more time on social media."}]$lyceon_json$::jsonb, 'B', NULL, E'This is an observational study: the researcher observed existing behavior without assigning treatments. Observational studies can establish an association between variables but cannot establish causation because confounding variables may be present. Claiming that social media causes lower GPAs or that reducing usage will improve GPAs both assert a causal relationship that this study design cannot support. Stating that students with lower GPAs are forced to spend more time on social media reverses the relationship and also asserts a causal mechanism without evidence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TO9PNK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What is the solution set of $\\frac{7}{x - 3} + \\frac{x}{x + 4} = \\frac{49}{(x - 3)(x + 4)}$?', NULL, $lyceon_json$[{"key":"A","text":"$\\{-7, 3\\}$"},{"key":"B","text":"$\\{-7\\}$"},{"key":"C","text":"$\\{3\\}$"},{"key":"D","text":"$\\{7\\}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Multiplying both sides by $(x - 3)(x + 4)$ yields $7(x + 4) + x(x - 3) = 49$. Expanding: $7x + 28 + x^2 - 3x = 49$, so $x^2 + 4x - 21 = 0$. Factoring: $(x + 7)(x - 3) = 0$, giving $x = -7$ or $x = 3$. However, $x = 3$ makes the denominator $x - 3$ equal to zero, so it is extraneous. The only valid solution is $x = -7$. The distractor $\\{-7, 3\\}$ includes the extraneous solution without checking domain restrictions. The distractor $\\{3\\}$ selects only the extraneous root, which is invalid. The distractor $\\{7\\}$ results from a sign error when solving the factored equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TW4KC5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $400$ residents in a city found that $62\\%$ support a new recycling program, with a margin of error of $\\pm 4\\%$. Which of the following is the best interpretation of the confidence interval?', NULL, $lyceon_json$[{"key":"A","text":"Between $58\\%$ and $66\\%$ of the sampled residents support the program."},{"key":"B","text":"It is plausible that between $58\\%$ and $66\\%$ of all residents in the city support the program."},{"key":"C","text":"Exactly $62\\%$ of all residents in the city support the program."},{"key":"D","text":"Between $58\\%$ and $66\\%$ of residents will support the program in the future."}]$lyceon_json$::jsonb, 'B', NULL, E'A confidence interval uses the sample statistic and margin of error to identify a plausible range for the population parameter. Here, $62\\% \\pm 4\\%$ means it is plausible that between $58\\%$ and $66\\%$ of all city residents support the program. Stating the interval applies only to the sampled residents misunderstands the purpose of inference, which is to generalize to the population. Claiming the population value is exactly $62\\%$ ignores sampling variability. Interpreting the interval as a prediction about future support confuses a confidence interval with a forecast.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U54NY0', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'grid_in', E'In triangle $ABC$, point $D$ lies on $\\overline{AB}$ and point $E$ lies on $\\overline{AC}$ such that $\\overline{DE} \\parallel \\overline{BC}$. If $AD = 9$, $DB = 6$, and $DE = 15$, what is the length of $BC$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '25', ARRAY['25'], E'Since $\\overline{DE} \\parallel \\overline{BC}$, triangles $ADE$ and $ABC$ are similar by the AA similarity criterion (they share $\\angle A$, and corresponding angles formed by the parallel lines and transversals are congruent). The ratio of similarity is $\\frac{AD}{AB} = \\frac{9}{9 + 6} = \\frac{9}{15} = \\frac{3}{5}$. Therefore $\\frac{DE}{BC} = \\frac{3}{5}$, giving $\\frac{15}{BC} = \\frac{3}{5}$, so $BC = \\frac{15 \\times 5}{3} = 25$. A common error is using $\\frac{AD}{DB}$ instead of $\\frac{AD}{AB}$, which gives $\\frac{9}{6} = \\frac{15}{BC}$ and $BC = 10$. Another error is forgetting to add $AD + DB$ to get $AB$ and instead using only $DB = 6$ as the denominator in a different incorrect ratio.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2U8UMJ2', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'The line $ax + 3y = 21$, where $a$ is a constant, passes through the point $(6, -5)$. What is the $x$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/2', ARRAY['7/2', '3.5'], E'First, find $a$ by substituting the point $(6, -5)$ into the equation: $6a + 3(-5) = 21$, so $6a - 15 = 21$, giving $6a = 36$ and $a = 6$. The equation becomes $6x + 3y = 21$. To find the $x$-intercept, set $y = 0$: $6x = 21$, so $x = \\frac{21}{6} = \\frac{7}{2}$. A common mistake is stopping after finding $a = 6$ without proceeding to compute the intercept, or substituting $x = 0$ instead of $y = 0$, which gives the $y$-intercept of $7$ rather than the $x$-intercept.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WOVJHL', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $\\frac{7(x - 3)}{5} = 14$?', NULL, $lyceon_json$[{"key":"A","text":"$-13$"},{"key":"B","text":"$10$"},{"key":"C","text":"$13$"},{"key":"D","text":"$17$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiply both sides by $5$ to obtain $7(x - 3) = 70$. Divide both sides by $7$ to get $x - 3 = 10$, then add $3$ to both sides to find $x = 13$. The value $10$ results from stopping at the intermediate step $x - 3 = 10$ without adding $3$. The value $17$ comes from incorrectly adding $3$ to $14$ without first clearing the fraction and the factor of $7$. The value $-13$ arises from a sign error during the final step.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XYXPN7', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A community theater charges a \\$29 registration fee plus \\$13 per rehearsal session. A performer has a budget of at most \\$250 for the season. What is the maximum number of rehearsal sessions the performer can attend?', NULL, $lyceon_json$[{"key":"A","text":"\\( 16 \\)"},{"key":"B","text":"\\( 17 \\)"},{"key":"C","text":"\\( 18 \\)"},{"key":"D","text":"\\( 19 \\)"}]$lyceon_json$::jsonb, 'B', NULL, E'The total cost is \\( 29 + 13s \\leq 250 \\), where \\( s \\) is the number of sessions. Subtracting 29 gives \\( 13s \\leq 221 \\). Dividing by 13 gives \\( s \\leq 17 \\), since \\( 13 \\times 17 = 221 \\) exactly. The maximum is 17 sessions. Choosing 16 results from a rounding error or mistakenly using strict inequality. Choosing 18 comes from neglecting to subtract the registration fee first, computing \\( 250 \\div 13 \\approx 19.2 \\) and then applying an incorrect adjustment. Choosing 19 comes from dividing 250 by 13 and rounding down without accounting for the registration fee at all.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Y79AJJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'An exponential model for the number of active users of a website is $y = 150(0.83)^x$, where $x$ is the number of years since $2015$ and $y$ is in thousands. According to this model, during which year will the number of active users first drop below $50$ thousand?', NULL, $lyceon_json$[{"key":"A","text":"$2019$"},{"key":"B","text":"$2020$"},{"key":"C","text":"$2021$"},{"key":"D","text":"$2022$"}]$lyceon_json$::jsonb, 'C', NULL, E'Setting $150(0.83)^x < 50$ gives $(0.83)^x < \\frac{1}{3}$. Testing integer values: $150(0.83)^5 \\approx 150(0.4013) \\approx 60.2$ (above $50$) and $150(0.83)^6 \\approx 150(0.3331) \\approx 49.97$ (below $50$). So $x = 6$ is the first integer year, and $2015 + 6 = 2021$. The year $2019$ results from using a linear decay model (e.g., solving $150 - 25x = 50$ to get $x = 4$). The year $2020$ results from computing $x \\approx 5.9$ and rounding down to $x = 5$, which still yields a value above $50$. The year $2022$ results from rounding $x \\approx 5.9$ up to $x = 7$ instead of identifying $x = 6$ as the first crossing.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YE72SE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two parallel lines are cut by a transversal. If one of the angles formed at the first intersection measures $137°$, what is the measure of the corresponding angle at the second intersection?', NULL, $lyceon_json$[{"key":"A","text":"$37°$"},{"key":"B","text":"$43°$"},{"key":"C","text":"$90°$"},{"key":"D","text":"$137°$"}]$lyceon_json$::jsonb, 'D', NULL, E'The correct answer is $137°$. When two parallel lines are cut by a transversal, corresponding angles are congruent, so the angle at the second intersection has the same measure as the one at the first. The value $43°$ results from computing the supplement $180° - 137°$, which gives a co-interior (same-side interior) angle, not a corresponding angle. The value $37°$ comes from an arithmetic error in subtracting from $180°$. The value $90°$ reflects a misconception that transversals always create right angles.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YP80CF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $13$ and a central angle of $\\frac{2\\pi}{5}$ radians. What is the length of the arc intercepted by this central angle?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13\\pi}{5}$"},{"key":"B","text":"$\\frac{26\\pi}{5}$"},{"key":"C","text":"$\\frac{52\\pi}{5}$"},{"key":"D","text":"$\\frac{338\\pi}{5}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The correct answer is $\\frac{26\\pi}{5}$. Arc length equals $r\\theta$, so the arc length is $13 \\times \\frac{2\\pi}{5} = \\frac{26\\pi}{5}$. The value $\\frac{13\\pi}{5}$ results from using $\\frac{\\pi}{5}$ instead of $\\frac{2\\pi}{5}$, effectively halving the central angle. The value $\\frac{52\\pi}{5}$ comes from using the diameter ($26$) instead of the radius in the formula. The value $\\frac{338\\pi}{5}$ results from computing $r^2\\theta = 169 \\times \\frac{2\\pi}{5}$, confusing the arc length formula with the sector area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YX3SGJ', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'If $a + b = 7$ and $a^2 + b^2 = 29$, what is the value of $a^3 + b^3$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '133', ARRAY['133'], E'First, find $ab$ using the identity $(a+b)^2 = a^2 + 2ab + b^2$. Substituting: $7^2 = 29 + 2ab$, so $49 = 29 + 2ab$, giving $2ab = 20$ and $ab = 10$. Next, use the factorization $a^3 + b^3 = (a+b)(a^2 - ab + b^2)$. We know $a + b = 7$, $a^2 + b^2 = 29$, and $ab = 10$, so $a^2 - ab + b^2 = 29 - 10 = 19$. Therefore $a^3 + b^3 = 7 \\times 19 = 133$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20YILR1', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Neither the lead conservator nor the two assistants who spent months restoring the seventeenth-century altarpiece ______ able to determine the precise origin of the pigment used in the central panel.', $lyceon_json$[{"key":"A","text":"was"},{"key":"B","text":"has been"},{"key":"C","text":"were"},{"key":"D","text":"is"}]$lyceon_json$::jsonb, 'C', NULL, E'When "neither...nor" connects two subjects, the verb agrees in number with the subject closer to the verb. Here, "the two assistants who spent months restoring the seventeenth-century altarpiece" is the nearer subject and is plural, so the verb must be plural. "Were" is the correct plural past-tense form. "Was" is wrong because it is singular, agreeing with "conservator" rather than the nearer subject "assistants." "Has been" is wrong because it is singular. "Is" is wrong because it is both singular and present tense. The long intervening relative clause "who spent months restoring the seventeenth-century altarpiece" makes this agreement harder to track, but the rule is determined by the nearer subject in the "neither...nor" construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
