INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW26OGHVV', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Recent surveys of deep-ocean sediment near hydrothermal vents in the Mid-Atlantic Ridge have revealed an unexpected diversity of fungal species. Marine mycologist Lena Torvik and her team cataloged thirty-seven previously undescribed species thriving at depths exceeding 3,200 meters. Many of these fungi exhibit bioluminescence, producing faint green or blue light through enzymatic reactions. Torvik hypothesizes that the bioluminescence may serve to attract invertebrates whose movements help disperse fungal spores across the otherwise barren seafloor.', $lyceon_json$[{"key":"A","text":"Researchers have discovered a surprising variety of fungi near deep-sea vents, some of which produce light that may aid in spore dispersal."},{"key":"B","text":"Hydrothermal vents in the Mid-Atlantic Ridge support more life than scientists previously believed possible at such depths."},{"key":"C","text":"Bioluminescence is a rare trait among fungi and is poorly understood by marine mycologists."},{"key":"D","text":"Lena Torvik's research methods have advanced the broader field of marine biology beyond traditional survey techniques."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on the discovery of diverse bioluminescent fungi near deep-sea hydrothermal vents and a hypothesis about the function of their light production. The choice stating that researchers discovered a surprising fungal variety with light that may aid spore dispersal captures both the finding and the hypothesis. The choice about vents supporting more life than expected broadens the scope beyond what the passage addresses. The choice calling bioluminescence rare and poorly understood contradicts the passage, which describes it as observed in many of the cataloged species. The choice about Torvik''s methods advancing marine biology is unsupported, since the passage does not discuss her methodology''s broader impact.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27G8JM4', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best describes the main idea of the text?', E'Epigenetic inheritance—the transmission of gene-regulation patterns without changes to DNA sequence—has been documented in the nematode Caenorhabditis elegans across as many as fourteen generations. Molecular biologist Ryo Ishikawa exposed nematodes to elevated temperatures, triggering expression of a heat-shock gene. Remarkably, descendants continued expressing this gene long after the thermal stimulus was removed. Ishikawa found that small RNA molecules, synthesized in response to the original stress, were passed through the germline and maintained the altered expression pattern. Yet when he disrupted a specific RNA-amplification enzyme, the inherited expression vanished within two generations. This result suggests that epigenetic memory in C. elegans is not passively carried but actively maintained by a molecular amplification loop.', $lyceon_json$[{"key":"A","text":"Multigenerational epigenetic inheritance in C. elegans depends on an active molecular mechanism rather than simple passive transmission."},{"key":"B","text":"Disrupting RNA-amplification enzymes in nematodes permanently eliminates their capacity for gene expression changes."},{"key":"C","text":"Elevated temperatures cause irreversible DNA mutations in C. elegans that mimic epigenetic inheritance."},{"key":"D","text":"Small RNA molecules are the sole factor responsible for all known forms of epigenetic inheritance across species."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how epigenetic inheritance persists across generations in C. elegans through small RNA molecules, then shows that disrupting the RNA-amplification enzyme causes the inherited expression to disappear quickly. The concluding sentence explicitly states that epigenetic memory is actively maintained, not passively carried. The choice about active molecular maintenance captures this central point. The choice about permanent elimination overstates the finding; the passage says expression vanished within two generations under disruption, not that the organism permanently lost the capacity for gene expression changes. The choice about irreversible DNA mutations contradicts the passage''s emphasis on epigenetic (non-DNA-sequence) changes. The choice about small RNAs being the sole factor across all species extends the finding far beyond the scope of the passage, which discusses only C. elegans.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW297T3F9', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The geochemist who identified high concentrations of lithium in the brine ______ presented her findings at a symposium in Reykjavík last October.', $lyceon_json$[{"key":"A","text":"pools,"},{"key":"B","text":"pools"},{"key":"C","text":"pools;"},{"key":"D","text":"pools—"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of this sentence is "The geochemist who identified high concentrations of lithium in the brine pools," with "who identified...pools" serving as a restrictive relative clause that is essential to identifying which geochemist is meant. No punctuation should separate this restrictive clause from the main verb "presented." The option with no punctuation after "pools" is correct. The option inserting a comma incorrectly separates the subject from its verb. The option using a semicolon fractures the sentence into a fragment before the semicolon and a fragment after it. The option using a dash similarly creates an ungrammatical break between the subject and its predicate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
