INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BSGY9R', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the rubber-processing techniques of ancient Mesoamerican peoples?', E'Archaeological chemist Daniela Fuentes analyzed rubber artifacts recovered from Olmec and Maya sites dating between 1600 BCE and 300 CE. She found that the rubber''s molecular structure varied systematically: balls used in the ceremonial ball game contained a high proportion of cross-linked polymer chains, making them highly elastic, while rubber strips used as adhesive bindings showed fewer cross-links and greater tackiness. Fuentes demonstrated through replication experiments that adding juice from the morning glory vine Ipomoea alba during processing increased cross-linking, whereas omitting it produced the stickier variant. Both forms were derived from the same latex of the Castilla elastica tree.', $lyceon_json$[{"key":"A","text":"Ancient Mesoamerican peoples intentionally modified the properties of natural rubber to suit different functional purposes."},{"key":"B","text":"The Olmec developed rubber processing before the Maya and later transmitted the technique through trade networks."},{"key":"C","text":"Castilla elastica trees were cultivated exclusively for rubber production and had no other uses in Mesoamerican societies."},{"key":"D","text":"The chemical composition of morning glory vine juice was well understood by ancient Mesoamerican chemists."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows two distinct rubber formulations—elastic balls and tacky adhesive strips—both made from the same latex but differing in the addition of morning glory juice. Since the two products have different physical properties suited to different uses, and the additive that controls those properties was either included or excluded, the inference that ancient peoples intentionally modified rubber for specific purposes is well supported. The choice about the Olmec transmitting techniques to the Maya introduces a chronological claim the passage does not make. The choice about exclusive cultivation of Castilla elastica overstates the evidence; the passage says nothing about other uses of the tree. The choice about chemical understanding attributes modern analytical knowledge to ancient peoples, which goes beyond what the passage supports—they could have discovered the technique empirically without understanding the chemistry.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CMXB5S', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The philosopher Kwame Gyekye argued that communitarian societies in West Africa did not suppress individual identity, as some Western scholars had claimed. Instead, he maintained that communal obligations and personal autonomy existed in a state of productive tension, each ________ the other: individuals gained purpose through communal roles, while communities drew vitality from members'' distinct contributions.', $lyceon_json$[{"key":"A","text":"sustaining"},{"key":"B","text":"depleting"},{"key":"C","text":"surveilling"},{"key":"D","text":"postponing"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "sustaining." The passage describes a reciprocal relationship in which individuals and communities each give vitality and purpose to the other — a relationship of mutual sustenance. "Depleting" means draining or exhausting, which directly contradicts the passage''s characterization of the relationship as productive and mutually beneficial. "Surveilling" means watching or monitoring, which introduces a notion of control that conflicts with the passage''s emphasis on productive tension rather than domination. "Postponing" means delaying and produces an incoherent sentence — one entity cannot meaningfully postpone another entity in this context.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DZ5HZJ', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about the role of mirror neurons in human empathy?', E'Neuroscientist Kenji Watanabe used functional MRI to monitor brain activity in 89 participants as they watched video clips of strangers experiencing mild pain—such as stubbing a toe or pricking a finger. He found that regions associated with mirror neuron activity were consistently activated when participants observed these events. However, the intensity of mirror neuron activation did not correlate with participants'' self-reported empathy scores on a validated questionnaire. Furthermore, seven participants with lesions in mirror neuron regions scored above the 90th percentile on the empathy questionnaire, while several participants with robust mirror neuron responses scored below the 25th percentile.', $lyceon_json$[{"key":"A","text":"Mirror neuron activation during pain observation is likely insufficient on its own to account for individual differences in empathic capacity."},{"key":"B","text":"Mirror neurons have no functional connection to the experience of empathy and are activated only by motor imitation tasks."},{"key":"C","text":"The empathy questionnaire used in the study was not a reliable measure of participants' actual empathic responses."},{"key":"D","text":"Participants with mirror neuron lesions developed alternative neural pathways that enhanced their empathic abilities beyond normal levels."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that mirror neurons are activated during pain observation but that activation intensity does not predict empathy scores, and some individuals with mirror neuron lesions score very high on empathy. Together, these findings suggest that mirror neuron activation alone cannot explain the full range of empathic capacity—other factors must contribute. The choice denying any connection between mirror neurons and empathy overstates the evidence; the passage shows they do activate during relevant observations, just that activation does not fully predict empathy. The choice questioning the questionnaire''s reliability introduces a methodological critique the passage does not raise—the questionnaire is described as validated. The choice about enhanced empathic abilities from alternative pathways goes beyond the data; the passage says some lesion patients scored high on empathy, but it does not claim their abilities were enhanced beyond normal or attribute this to compensatory pathways.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2E1AZHB', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying the seafloor near hydrothermal vents were surprised to find thriving colonies of tube worms at depths previously thought inhospitable. The discovery ________ earlier assumptions that complex organisms could not survive without sunlight as an energy source.', $lyceon_json$[{"key":"A","text":"contradicted"},{"key":"B","text":"ignored"},{"key":"C","text":"predicted"},{"key":"D","text":"funded"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "contradicted." The passage describes a discovery that went against what scientists previously believed, meaning it contradicted those assumptions. "Ignored" implies a deliberate act of disregarding, but a discovery does not choose to ignore anything — it provides evidence against something. "Predicted" reverses the logical direction: the discovery came after the assumptions, not before them. "Funded" refers to financial support and has no meaningful connection to challenging scientific assumptions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F1Z4T5', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'According to the text, what is the primary reason that Safavid-era astronomical instruments have attracted renewed scholarly attention?', E'For decades, Safavid-era astronomical instruments crafted in seventeenth-century Isfahan were studied mainly as decorative artifacts. However, historian Parisa Gholami has demonstrated that the engraved calibration marks on several surviving astrolabes correspond precisely to stellar coordinates recorded in the Zij-i Sultani, a set of astronomical tables compiled under Ulugh Beg in the fifteenth century. Gholami argues that these instruments were not merely ornamental but were functional tools whose makers deliberately preserved an older, highly accurate observational tradition. Her findings have prompted other scholars to reexamine similar instruments held in European museum collections, seeking evidence of comparable calibration precision.', $lyceon_json$[{"key":"A","text":"New evidence suggests that the instruments were precise functional tools connected to an established observational tradition."},{"key":"B","text":"The instruments have been found to contain materials that are chemically distinct from those used in other Islamic metalwork."},{"key":"C","text":"European museums have recently acquired large numbers of previously unknown Safavid instruments."},{"key":"D","text":"Advances in digital imaging technology have made it possible to study the instruments without handling them directly."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Gholami demonstrated the instruments'' calibration marks align with historical stellar coordinates, proving they were functional tools preserving an older observational tradition. This finding is what prompted renewed scholarly attention. The choice about chemically distinct materials is fabricated; the passage says nothing about material composition. The choice about European museums acquiring large numbers of instruments misreads the text, which mentions scholars reexamining instruments already held in collections. The choice about digital imaging technology introduces information absent from the passage entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FAX7Y0', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student wants to emphasize the paradox in glassfrogs'' transparency. Which choice most effectively uses relevant information from the notes to accomplish this goal?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GXALCF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the overall purpose of the text?', E'Critics of vertical farming often cite its enormous energy consumption: growing lettuce indoors under LED lights can require forty times more electricity per kilogram than field cultivation. Proponents counter that vertical farms eliminate transportation emissions, reduce pesticide runoff, and reclaim arable land for carbon-sequestering forests. Yet neither side adequately accounts for the variability in regional energy grids. A vertical farm powered by Icelandic geothermal energy has a radically different carbon profile from one drawing on a coal-heavy grid in eastern Poland, making blanket claims about vertical farming''s sustainability misleading in either direction.', $lyceon_json$[{"key":"A","text":"to argue that vertical farming should replace traditional agriculture in regions with renewable energy infrastructure"},{"key":"B","text":"to demonstrate that critics of vertical farming have stronger evidence than its proponents do"},{"key":"C","text":"to show that evaluating vertical farming's environmental impact requires attention to a factor that both sides of the debate tend to overlook"},{"key":"D","text":"to trace the historical development of vertical farming technology from its inception to its current state"}]$lyceon_json$::jsonb, 'C', NULL, E'The correct answer is the choice stating that the text shows evaluating vertical farming''s environmental impact requires attention to an overlooked factor. The passage presents arguments from both critics and proponents, then pivots to argue that neither side accounts for regional energy grid variability — a factor that fundamentally changes the analysis. The choice about replacing traditional agriculture overreaches beyond the text, which critiques the framing of the debate rather than advocating for vertical farming adoption. The choice about critics having stronger evidence misreads the text''s balanced presentation; the passage faults both sides equally for ignoring grid variability. The choice about tracing historical development is wrong because the passage contains no chronological history of the technology.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JD2353', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'The blanket octopus is one of the few marine animals exhibiting extreme sexual dimorphism: females can grow to nearly two meters in length, while males rarely exceed three centimeters. This size difference has practical implications for the species'' defensive strategies. Females unfurl long, webbed membranes to appear larger and deter predators. Males, _________ rely on a borrowed defense, carrying broken tentacles from Portuguese man-of-war jellyfish to sting potential threats.', $lyceon_json$[{"key":"A","text":"in addition,"},{"key":"B","text":"by contrast,"},{"key":"C","text":"in other words,"},{"key":"D","text":"as a result,"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes two sharply different defensive strategies used by female and male blanket octopuses: females unfurl membranes, while males carry stolen jellyfish tentacles. "By contrast," correctly signals this opposition between the two approaches. "In addition," would suggest the male strategy simply supplements the female one, but the passage frames them as distinct alternatives tied to size differences. "In other words," would restate the previous idea in different terms, yet the male strategy is an entirely separate behavior, not a rephrasing. "As a result," implies a causal link — that the female strategy directly produces or causes the male strategy — which the passage does not support.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JKE42G', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support Lindqvist''s hypothesis?', E'Entomologist Maja Lindqvist has proposed that honeybees navigating over open water rely on the polarization pattern of skylight rather than on visual landmarks. She notes that bees crossing large lakes maintain remarkably straight flight paths even when no shoreline or surface feature is visible. Lindqvist hypothesizes that receptors in the bee''s dorsal eye region detect the orientation of polarized light, providing a directional reference analogous to a compass.', $lyceon_json$[{"key":"A","text":"Bees with experimentally obscured dorsal eye receptors fly in erratic paths over open water but navigate normally over land with visible landmarks."},{"key":"B","text":"Honeybees preferentially forage at flowers located near reflective bodies of water."},{"key":"C","text":"The polarization pattern of skylight shifts measurably between dawn and midday."},{"key":"D","text":"Several other insect species also maintain straight flight paths when crossing open water."}]$lyceon_json$::jsonb, 'A', NULL, E'Lindqvist''s hypothesis is that dorsal eye receptors detect polarized skylight to guide bees over open water. The finding that obscuring those receptors disrupts flight over water but not over land with landmarks directly supports the claim, because it shows the receptors are specifically necessary when landmarks are absent. The choice about foraging near reflective water addresses bee behavior unrelated to navigation mechanics. The choice about polarization patterns shifting between dawn and midday describes a property of light but does not connect it to bee navigation. The choice about other insect species crossing water shows the behavior is common but provides no evidence about the mechanism Lindqvist proposes.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KAKTM3', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologists working in northern Peru have long assumed that the Moche civilization declined primarily due to prolonged drought. Recent isotope analysis of sediment cores from the region, _________ confirms that the area experienced above-average rainfall during the period of Moche collapse, suggesting that other factors were responsible.', $lyceon_json$[{"key":"A","text":"however,"},{"key":"B","text":"similarly,"},{"key":"C","text":"for instance,"},{"key":"D","text":"consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage sets up a contrast: archaeologists assumed drought caused the decline, but new evidence shows above-average rainfall. The transition "however," correctly signals this contradiction. "Similarly," implies agreement between the two ideas, which is the opposite of the relationship presented. "For instance," would introduce a specific example illustrating a prior claim, but the second sentence contradicts rather than illustrates the first. "Consequently," implies the second idea follows logically from the first, but the new evidence undermines rather than follows from the original assumption.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KYM111', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The grant proposal outlined three objectives: cataloging the butterfly species of the Dinaric Alps, ______ the migratory corridors used by alpine swifts, and publishing the results in a peer-reviewed journal.', $lyceon_json$[{"key":"A","text":"mapping"},{"key":"B","text":"to map"},{"key":"C","text":"she mapped"},{"key":"D","text":"maps"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence lists three objectives in a series separated by commas: "cataloging...Alps," "______ the migratory corridors...," and "publishing...journal." Parallel structure requires that all three items in this series take the same grammatical form. Since "cataloging" and "publishing" are gerunds (present participles functioning as nouns), the second item must also be a gerund. "Mapping" maintains the parallel gerund form. "To map" breaks parallelism by switching to an infinitive. "She mapped" breaks parallelism by introducing a finite clause with a new subject. "Maps" breaks parallelism by using a simple present-tense verb rather than a gerund.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MRWFEV', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Certain species of octopus can alter the color and texture of their skin in less than a second. This camouflage ability relies on specialized cells called chromatophores, which contain pigment sacs that expand or contract in response to neural signals. <u>Remarkably, octopuses achieve this feat despite being colorblind.</u> Researchers believe the animals may detect light wavelengths through photoreceptors embedded directly in their skin.', $lyceon_json$[{"key":"A","text":"to introduce a surprising detail that complicates the explanation presented earlier in the text"},{"key":"B","text":"to provide a specific example of a chromatophore functioning in a laboratory setting"},{"key":"C","text":"to summarize the main finding of a research study on octopus vision"},{"key":"D","text":"to define a technical term that is central to the passage's argument"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice stating that the sentence introduces a surprising detail that complicates the earlier explanation. The underlined sentence reveals that octopuses are colorblind despite having remarkable color-changing abilities, which creates a paradox that the final sentence then addresses. The choice about a laboratory example is wrong because the underlined sentence does not describe any laboratory setting or specific experiment. The choice about summarizing a main finding mischaracterizes the sentence, which presents a complication rather than a conclusion. The choice about defining a technical term is wrong because the underlined sentence defines no term — the technical term "chromatophores" was defined in the preceding sentence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NZKPCN', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Lichen communities are widely used as bioindicators of air quality because many species are highly sensitive to sulfur dioxide and nitrogen oxides. In heavily polluted urban districts, lichen diversity typically drops to near zero. Ecologist Marta Quintero documented an unexpected pattern in the industrial port city of Cartagena, Colombia: certain crustose lichen species were thriving on concrete walls adjacent to a petrochemical refinery. _________ Quintero''s finding does not undermine the bioindicator model. Her analysis revealed that the surviving species belong to a nitrophilic clade that actually metabolizes nitrogen compounds as a nutrient source, meaning their presence signals nitrogen-rich pollution rather than clean air.', $lyceon_json$[{"key":"A","text":"Nevertheless,"},{"key":"B","text":"Specifically,"},{"key":"C","text":"Importantly,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence following the blank clarifies that Quintero''s seemingly contradictory finding does not actually undermine the bioindicator model — a point the author emphasizes as significant for correctly interpreting the data. "Importantly," signals that what follows is a crucial qualification the reader should not overlook. "Nevertheless," would imply the sentence contradicts the finding about thriving lichens, but the sentence actually reconciles that finding with the bioindicator model rather than opposing it. "Specifically," would introduce a narrowing detail that elaborates on the previous sentence, but the sentence that follows shifts from describing the observation to defending the broader model. "Meanwhile," signals a simultaneous but separate event, which does not match the logical relationship here — the sentence directly addresses the implication of Quintero''s finding rather than introducing a parallel occurrence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OM76LJ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, the physician Ignaz Semmelweis noticed that women in a maternity ward staffed by medical students died of puerperal fever at nearly five times the rate of those in a ward staffed by midwives. He hypothesized that students were transferring infectious material from cadaver dissections to patients. When Semmelweis instituted mandatory handwashing with a chlorinated lime solution, mortality in the affected ward dropped from 18 percent to under 2 percent. Despite these results, most of the medical establishment rejected his proposal, viewing handwashing as an unnecessary inconvenience.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a proposed explanation and its successful test, and then notes the resistance that the proposal encountered"},{"key":"B","text":"It contrasts two competing hypotheses about a medical condition and then evaluates which hypothesis has stronger experimental support"},{"key":"C","text":"It narrates a physician's career in chronological order, highlighting the honors received for groundbreaking work"},{"key":"D","text":"It describes a medical procedure and then explains why that procedure was eventually adopted universally"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is the choice describing the text as presenting an observation, a proposed explanation with a successful test, and noting resistance. The passage follows exactly that structure: Semmelweis observed differing mortality rates, hypothesized a cause, tested it via handwashing with dramatic results, and yet faced rejection. The choice about contrasting two competing hypotheses is wrong because the passage presents only Semmelweis''s hypothesis, not a rival one. The choice about narrating a career and highlighting honors misrepresents the passage, which covers a single episode and ends with rejection rather than recognition. The choice about explaining universal adoption contradicts the passage, which explicitly states the medical establishment rejected the proposal.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2P6TEY7', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about silk production for a general audience. Which choice most effectively uses relevant information from the notes to introduce the topic?', E'Notes:
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PMB1FT', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although preliminary surveys of the cave system near Trebinje suggested that the limestone formations were relatively ______ radiocarbon dating of embedded organic material later confirmed that the oldest stalagmites had been growing for over forty thousand years.', $lyceon_json$[{"key":"A","text":"recent;"},{"key":"B","text":"recent."},{"key":"C","text":"recent,"},{"key":"D","text":"recent"}]$lyceon_json$::jsonb, 'C', NULL, E'The entire clause beginning with "Although" and ending with "recent" is a dependent clause introduced by the subordinating conjunction "Although." This dependent clause must be joined to the following independent clause with a comma. The option using a comma after "recent" is correct. The option using a semicolon is wrong because a semicolon cannot join a dependent clause to an independent clause—it requires two independent clauses. The option using a period is wrong because it turns everything from "Although" through "recent" into a sentence fragment. The option with no punctuation is wrong because a comma is required after an introductory dependent clause, especially one this long. The difficulty here lies in tracking the subordinating conjunction "Although" through the extended dependent clause with multiple embedded clauses.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QRJLE5', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding from Okoro''s study would most directly weaken the claim that first-language attrition in bilingual adults is primarily caused by reduced frequency of first-language use?', E'Sociolinguist Adaeze Okoro studied 143 bilingual adults who emigrated from Nigeria to Germany between the ages of 22 and 30. All participants reported using their first language, Igbo, less than five hours per week after emigrating. Okoro measured participants'' Igbo lexical retrieval speed and grammatical accuracy at three-year intervals over a twelve-year period. The prevailing theory holds that first-language attrition in adult bilinguals results primarily from diminished frequency of first-language use—a disuse-based model that predicts a roughly linear decline in proficiency proportional to reduced exposure.', $lyceon_json$[{"key":"A","text":"Participants who reported the lowest weekly hours of Igbo use showed no greater decline in lexical retrieval speed than participants who reported somewhat higher usage within the same low-use range."},{"key":"B","text":"Participants' German proficiency improved steadily over the twelve-year period regardless of their initial level of German at the time of emigration."},{"key":"C","text":"Participants who had completed university education in Igbo before emigrating scored higher on grammatical accuracy at every measurement point."},{"key":"D","text":"The overall rate of lexical retrieval decline was steepest during the first three years after emigration and then stabilized for the remaining nine years."}]$lyceon_json$::jsonb, 'A', NULL, E'The disuse-based model predicts that less use leads to proportionally greater attrition. If participants with the least Igbo use showed no greater decline than those with somewhat more use in the same low range, the expected dose-response relationship is absent, directly undermining the frequency-based explanation. The finding about German proficiency improving addresses the second language, not first-language attrition mechanisms. The finding about university-educated participants scoring higher concerns initial proficiency advantages, not the mechanism of attrition. The finding about decline being steepest early and then stabilizing is compatible with the disuse model if one allows for a floor effect; it does not directly contradict the claim that reduced use is the primary cause, since the early period also represents the most abrupt usage change.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QU19PC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'During the 1930s, the Mexican muralist movement attracted artists who believed that painting should serve a civic function rather than remain the exclusive province of galleries and collectors. By placing monumental works on public buildings, these artists sought to ________ the boundary between fine art and everyday life, making aesthetic experience available to workers and passersby alike.', $lyceon_json$[{"key":"A","text":"dissolve"},{"key":"B","text":"photograph"},{"key":"C","text":"construct"},{"key":"D","text":"memorize"}]$lyceon_json$::jsonb, 'A', NULL, E'The correct answer is "dissolve." The passage describes artists who wanted to eliminate the separation between fine art and daily life by making art publicly accessible, so dissolving a boundary fits the intended meaning. "Photograph" refers to capturing images and makes no sense as something done to a boundary. "Construct" means to build, which is the opposite of what the artists intended — they wanted to remove the boundary, not create one. "Memorize" means to commit to memory and produces a nonsensical sentence when applied to a boundary between art and life.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RUYYE9', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of nineteenth-century nautical instruments ______ on permanent display at the maritime museum in Gdańsk.', $lyceon_json$[{"key":"A","text":"are"},{"key":"B","text":"is"},{"key":"C","text":"were"},{"key":"D","text":"have been"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of this sentence is "collection," a singular noun. The prepositional phrase "of nineteenth-century nautical instruments" modifies "collection" but does not change the number of the subject. The singular present-tense verb "is" correctly agrees with "collection." The option "are" is wrong because it treats the plural "instruments" as the subject. The option "were" is wrong because it is both plural and past tense, neither of which matches the singular present-tense context. The option "have been" is wrong because it is a plural verb form that fails to agree with the singular subject "collection."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TFA6NJ', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Constructed entirely from reclaimed timber and hand-forged iron, ______', $lyceon_json$[{"key":"A","text":"hikers from across the region have been attracted to the footbridge spanning the gorge near Konjic."},{"key":"B","text":"the gorge near Konjic is now spanned by a footbridge that has attracted hikers from across the region."},{"key":"C","text":"attracting hikers from across the region to the gorge near Konjic has been one accomplishment of a remarkable footbridge."},{"key":"D","text":"the footbridge spanning the gorge near Konjic has attracted hikers from across the region."}]$lyceon_json$::jsonb, 'D', NULL, E'The introductory participial phrase "Constructed entirely from reclaimed timber and hand-forged iron" must modify the noun that immediately follows the comma—this noun must be the thing that was constructed. Only the option beginning with "the footbridge" places the correct noun in the subject position, because the footbridge is what was constructed from reclaimed timber and iron. The option beginning with "hikers" creates a dangling modifier, implying hikers were constructed from timber and iron. The option beginning with "the gorge" similarly dangles the modifier, implying the gorge was constructed. The option beginning with "attracting" places a gerund phrase as the subject, wrongly implying that the act of attracting was constructed from timber and iron.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UQYBII', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'What can most reasonably be inferred from the text about the relationship between lichen and air quality?', E'Ecologist Tomás Herrera surveyed lichen communities on oak trees in seventeen neighborhoods across Santiago, Chile. In districts with heavy vehicular traffic and industrial activity, he found only three lichen species, all with thick, crusty growth forms. In contrast, residential neighborhoods with minimal traffic supported as many as nineteen species, including delicate, leaf-like forms. Herrera noted that the sensitive species disappeared first as sulfur dioxide concentrations increased.', $lyceon_json$[{"key":"A","text":"Certain lichen species are unable to tolerate elevated levels of air pollution, making lichen diversity a potential indicator of air quality."},{"key":"B","text":"Lichen communities cause air quality to improve in residential neighborhoods by absorbing sulfur dioxide from the atmosphere."},{"key":"C","text":"Oak trees in polluted areas are less healthy than those in residential neighborhoods, which explains the reduced lichen diversity."},{"key":"D","text":"All lichen species will eventually disappear from urban areas as global air pollution levels continue to rise."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage shows that lichen diversity is lower in polluted areas and that sensitive species disappear as sulfur dioxide rises. The reasonable inference is that some species cannot tolerate pollution and that lichen diversity reflects air quality. The choice about lichen absorbing sulfur dioxide reverses the relationship described in the passage; the text says lichen are affected by pollution, not that they remediate it. The choice about oak tree health introduces an explanation the passage never suggests. The choice predicting total lichen disappearance globally extends the local observation far beyond what the text supports.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WNEAWS', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the marine biologist had spent seventeen years cataloging reef formations along the Andaman ______ she acknowledged that much of the underwater terrain remained unmapped.', $lyceon_json$[{"key":"A","text":"coast,"},{"key":"B","text":"coast;"},{"key":"C","text":"coast."},{"key":"D","text":"coast"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with the subordinating conjunction "Although," creating a dependent clause that must be joined to the independent clause with a comma. The option using a comma after "coast" correctly punctuates this boundary. The option using a semicolon is wrong because a semicolon cannot join a dependent clause to an independent clause. The option using a period is wrong because it turns "Although the marine biologist had spent seventeen years cataloging reef formations along the Andaman coast" into a sentence fragment. The option with no punctuation is wrong because Standard English requires a comma after an introductory dependent clause.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XA6166', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the 1970s, linguist William Labov demonstrated that speakers of non-standard dialects often apply grammatical rules as consistently as speakers of prestige dialects do — the rules are simply different. His research on African American Vernacular English showed that features such as habitual "be" and negative concord follow systematic, predictable patterns. _________ some language educators began incorporating Labov''s findings into pedagogy, designing curricula that treated dialect differences as rule-governed variation rather than errors to be corrected. This approach, known as contrastive analysis, asks students to compare their home dialect''s grammar with Standard English grammar, building metalinguistic awareness without stigmatizing either system.', $lyceon_json$[{"key":"A","text":"In turn,"},{"key":"B","text":"On the contrary,"},{"key":"C","text":"For example,"},{"key":"D","text":"Granted,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage traces a sequential chain: Labov''s research established that non-standard dialects follow systematic rules, and then educators responded by redesigning curricula accordingly. "In turn," correctly conveys this responsive, consequential sequence — one development leading to the next. "On the contrary," signals direct opposition, but the educators'' curricular changes grew out of Labov''s findings rather than contradicting them. "For example," would introduce a specific instance illustrating the previous claim about habitual "be" or negative concord, but the sentence instead shifts to a new development in educational practice. "Granted," introduces a concession the author plans to counter, but the passage does not counter or qualify the educators'' approach — it describes it approvingly and explains how it works.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YDX6CC', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a research article would most effectively support the claim that Roman maritime concrete gains strength from prolonged seawater exposure?', E'Engineers have long marveled at the durability of Roman harbor structures, many of which have withstood two millennia of wave action. Recent analyses of core samples from the ancient port of Baiae reveal that seawater percolating through the concrete triggers a mineral growth process: aluminous tobermorite crystals form within the calcium-aluminum-silicate matrix, filling micro-cracks and binding aggregate particles more tightly over time. This contrasts sharply with modern Portland cement concrete, which deteriorates when exposed to saltwater.', $lyceon_json$[{"key":"A","text":"\"Samples submerged in synthetic seawater for 18 months exhibited a 12 percent increase in compressive strength, with tobermorite crystal density rising in proportion to exposure duration.\""},{"key":"B","text":"\"The volcanic ash sourced from the Campi Flegrei region contains a higher proportion of alumina than ash from other Mediterranean volcanic sites.\""},{"key":"C","text":"\"Portland cement production accounts for approximately 8 percent of global carbon dioxide emissions, prompting interest in alternative binders.\""},{"key":"D","text":"\"Roman builders transported pozzolanic ash by ship from Pozzuoli to construction sites as distant as Caesarea Maritima in modern-day Israel.\""}]$lyceon_json$::jsonb, 'A', NULL, E'The claim is that Roman maritime concrete becomes stronger through prolonged seawater exposure. The quotation reporting a measurable increase in compressive strength correlated with exposure duration and tobermorite crystal growth directly supports this claim. The quotation about alumina content in volcanic ash describes a raw material property but does not address strength changes from seawater exposure. The quotation about Portland cement emissions concerns environmental impact, which is unrelated to the durability claim. The quotation about transporting pozzolanic ash describes logistics of Roman construction, not the effect of seawater on concrete strength.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YW571W', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The architect Maren ______ who redesigned the waterfront promenade in the port city of Stavanger, was honored with Norway''s highest award for urban design.', $lyceon_json$[{"key":"A","text":"Solvig,"},{"key":"B","text":"Solvig"},{"key":"C","text":"Solvig;"},{"key":"D","text":"Solvig—"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause "who redesigned the waterfront promenade in the port city of Stavanger" is nonrestrictive—it provides additional information about Maren Solvig, who has already been identified by name. Nonrestrictive clauses must be set off by paired punctuation. Because the closing boundary after "Stavanger" already uses a comma, the opening boundary must also use a comma: "Solvig, who redesigned...Stavanger, was honored." The option placing a comma after "Solvig" correctly opens this pair. The option with no punctuation fails to mark the nonrestrictive clause. The option using a semicolon creates a sentence fragment before the semicolon. The option using a dash creates a mismatched pair—an opening dash paired with a closing comma—which violates the convention that parenthetical punctuation must match.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
